from collections.abc import Callable, Coroutine
from typing import Any

from fastapi import APIRouter, FastAPI
from fastapi.routing import APIRoute
from fastapi.testclient import TestClient
from starlette.requests import Request
from starlette.responses import Response


class AuditedRoute(APIRoute):
    accessed: list[str] = []

    def get_route_handler(
        self,
    ) -> Callable[[Request], Coroutine[Any, Any, Response]]:
        original_handler = super().get_route_handler()
        route = self

        async def audited_handler(request: Request) -> Response:
            type(self).accessed.append(route.path)
            return await original_handler(request)

        return audited_handler


def test_route_class_map_selects_class_by_http_method() -> None:
    AuditedRoute.accessed.clear()

    router = APIRouter(route_class_map={"POST": AuditedRoute})

    @router.get("/items")
    def get_items() -> dict[str, list[dict[str, str]]]:
        return {"items": []}

    @router.post("/items")
    def create_item() -> dict[str, bool]:
        return {"created": True}

    app = FastAPI()
    app.include_router(router)
    client = TestClient(app)

    get_response = client.get("/items")
    post_response = client.post("/items")

    assert get_response.status_code == 200
    assert get_response.json() == {"items": []}
    assert post_response.status_code == 200
    assert post_response.json() == {"created": True}

    assert AuditedRoute.accessed == ["/items"]


def test_route_class_map_uses_correct_route_class_per_method() -> None:
    AuditedRoute.accessed.clear()

    router = APIRouter(route_class_map={"POST": AuditedRoute})

    @router.get("/items")
    def get_items() -> dict[str, list[dict[str, str]]]:
        return {"items": []}

    @router.post("/items")
    def create_item() -> dict[str, bool]:
        return {"created": True}

    get_route = next(route for route in router.routes if route.methods == {"GET"})
    post_route = next(route for route in router.routes if route.methods == {"POST"})

    assert isinstance(get_route, APIRoute)
    assert not isinstance(get_route, AuditedRoute)
    assert isinstance(post_route, AuditedRoute)


def test_route_class_map_falls_back_to_default_when_method_not_mapped() -> None:
    AuditedRoute.accessed.clear()

    router = APIRouter(route_class=APIRoute, route_class_map={"POST": AuditedRoute})

    @router.get("/items")
    def get_items() -> dict[str, list[dict[str, str]]]:
        return {"items": []}

    get_route = next(route for route in router.routes if route.methods == {"GET"})

    assert type(get_route) is APIRoute
    assert not isinstance(get_route, AuditedRoute)

